const body = $json.body || $json;
const p = body.payload || body;
const email = p.email || body.email || null;
if (!email) throw new Error('email required');

const props = { email };
if (p.first_name)       props.firstname              = p.first_name;
if (p.last_name)        props.lastname               = p.last_name;
if (p.phone)            props.phone                  = p.phone;
if (p.company)          props.company                = p.company;
if (p.industry)         props.industry               = p.industry;
if (p.city)             props.city                   = p.city;
if (p.address)          props.address                = p.address;
if (p.colonia)          props.colonia                = p.colonia;
if (p.postal_code)      props.zip                    = p.postal_code;
if (p.website)          props.website                = p.website;
if (p.linkedin)         props.hs_linkedin_url        = p.linkedin;
if (p.contact_linkedin) props.contact_linkedin       = p.contact_linkedin;
if (p.facebook)         props.hs_facebookid          = p.facebook;
if (p.instagram)        props.instagram              = p.instagram;
if (p.whatsapp)         props.hs_whatsapp_phone_number = p.whatsapp;
if (p.secondary_phone)  props.secondary_phone        = p.secondary_phone;
if (p.job_title)        props.jobtitle               = p.job_title;
if (p.pain_points)      props.cx_pain_points         = p.pain_points;
if (p.pci != null)      props.cx_pci                 = String(p.pci);
if (p.source)           props.fuente                 = p.source;
if (p.status)           props.hs_lead_status         = p.status.toUpperCase();

return [{
  json: {
    email,
    session_id: body.session_id || null,
    properties: props
  }
}];

